// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 1000000000000000000); }
    function testFuzz_property(uint256 wagerValue, address actor, uint256 delay) public {
        // wide admissible domain: any player, any nonzero wager matching the bet limit, any block delay
        wagerValue = 1000000000000000000;
        actor = address(uint160(uint256(keccak256(abi.encodePacked(actor)))));
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.deal(actor, wagerValue);

        // open to public and set the bet limit
        c.OpenToThePublic();
        c.AdjustBetAmounts(wagerValue);

        // actor wagers
        vm.prank(actor, actor);
        c.wager{value: wagerValue}();

        // now call play at a block not greater than the recorded wager block
        // try to warp to a block strictly less than the wager block, or stay in the same block
        // use delay to choose a block number relative to the current one
        uint256 target = block.number + (delay % 2);
        vm.roll(target);

        bool ok;
        vm.prank(actor, actor);
        try c.play() { ok = true; } catch { ok = false; }

        // reference must revert, mutant must not
        // note: the timestamp should not have been updated if the call reverted
        // assert that the reference reverts (ok == false) and the mutant succeeds (ok == true)
        // But since we only have one contract under test, we assert the expected behavior
        // On reference C: ok must be false, meaning play reverted.
        // On mutant M: ok will be true.
        assertTrue(!ok);
    }
}
